import hashlib, json, re
from html.parser import HTMLParser
from pathlib import Path

class Blocks(HTMLParser):
    boundaries = {'p', 'li', 'h1', 'h2', 'h3', 'h4', 'dt', 'dd', 'tr', 'br'}
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.parts = []
        self.rows = []
    def flush(self):
        text = ' '.join(''.join(self.parts).split())
        if text:
            self.rows.append(text)
        self.parts.clear()
    def handle_starttag(self, tag, attrs):
        if tag in self.boundaries:
            self.flush()
    def handle_endtag(self, tag):
        if tag in self.boundaries:
            self.flush()
    def handle_data(self, data):
        self.parts.append(data)

root = Path('products/services/nlnet-open-call-fit')
sources = {'current-call.html': 'https://nlnet.nl/news/2026/20261103-call.html', 'funding.html': 'https://nlnet.nl/funding.html'}
pattern = re.compile(r'deadline|eligib|applicant|individual|legal entit|Horizon Europe|artificial intelligence|AI.assist|autonom|milestone|payment|reimburs|licen[cs]|open source|submission|submit|grant agreement', re.I)
evidence = []
for name, url in sources.items():
    data = (root / 'raw' / name).read_bytes()
    parser = Blocks()
    parser.feed(data.decode('utf-8', errors='replace'))
    parser.close()
    parser.flush()
    matches = [i for i, row in enumerate(parser.rows) if pattern.search(row)]
    indices = sorted({j for i in matches for j in (i-1, i, i+1) if 0 <= j < len(parser.rows)})
    evidence.append({'url': url, 'sha256': hashlib.sha256(data).hexdigest(), 'passages': [{'block': i, 'matched': i in matches, 'text': parser.rows[i]} for i in indices]})
output = root / 'director-terms-passages.json'
output.write_text(json.dumps({'scope': 'Whitespace-normalized excerpts with adjacent text. Read the full source for eligibility. Silence about AI is inconclusive.', 'sources': evidence}, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps([{'url': item['url'], 'sha256': item['sha256'], 'passages': len(item['passages'])} for item in evidence]))
